-- SmartAI from TrinityCore 3.3.5 (TDB_full_world_335.26091_2026_09_09), taken after the Cata Classic import for creatures this core leaves unscripted (S5):
-- 17 creature scripts and 4 single-spawn scripts, 107 rows, 9 timed action lists.
-- Translated row by row; see skyfire_port_plan/tools/dbcompare/s5_tc_smart_scripts.py. TrinityCore world DB, GPL v2.
-- Safe to run twice.

-- Scripts. A script is only added while that creature, spawn or action list still has no rows.
DROP TEMPORARY TABLE IF EXISTS `tmp_s5_smart`;
CREATE TEMPORARY TABLE `tmp_s5_smart` LIKE `smart_scripts`;
DELETE t FROM `tmp_s5_smart` t JOIN (SELECT DISTINCT `entryorguid`, `source_type` FROM `smart_scripts`) x ON x.`entryorguid` = t.`entryorguid` AND x.`source_type` = t.`source_type`;
DROP TEMPORARY TABLE `tmp_s5_smart`;

-- Paths those scripts walk: 21 points on 4 paths (only added where the path id is still free)

-- Lines those scripts say: 27 rows in 16 text groups

-- Switch the scripts on
UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `AIName` = '' AND `ScriptName` = '' AND `entry` IN (4437,4511,4538,4541,5409,8996,14121,14844,14845,16800,16801,17663,18528,19294,23141,24340,24846,25335,28605,30246);
